-- V353__weighment_capture_reload_loading_second_weight.sql
-- aria:weighment-capture's weight_seq computed field (tenant-1 override,
-- page_id resolved by code below) mapped M10.TankerOutbound's RELOAD_LOADING
-- state to 'FIRST' — the same bucket as QC_PRELOAD_APPROVED/RELOAD_REQUIRED.
-- That hid the "Order Details — Per-SKU Weight Capture" section (the
-- tankerSkuWeights ListView whose Save button calls
-- m10.tanker-weighment-capture) at RELOAD_LOADING, since that section is
-- only visibleWhen weight_seq == 'SECOND'. Without it, an operator reaching
-- RELOAD_LOADING had no on-screen way to weigh/consume the fresh IN_PROGRESS
-- rows TankerOutboundReloadReseedListener seeds on UNLOADING_WEIGHMENT ->
-- RELOAD_LOADING — "Capture & Save Weighment" would silently advance
-- RELOAD_LOADING -> LOADING_COMPLETED without ever re-consuming stock.
--
-- Fix: move RELOAD_LOADING from the FIRST branch to the SECOND branch in
-- M10.TankerOutbound's segment of the weight_seq ternary only — every other
-- workflow's segment (FGLoading, PackLoading, TankerInbound, PackUnload,
-- ReturnStockIn, FGUnloading, StockInward) and every other field on this
-- shared page are untouched; verified by diffing the full page body with
-- only the weight_seq node's computedFrom stripped out — identical.
--
-- Guarded by LOCATE (not LIKE, to avoid '_'/'%' being treated as wildcards
-- against identifiers like RELOAD_LOADING) against the exact pre-fix
-- substring, so re-running this migration after the fix is already live is
-- a no-op rather than publishing a duplicate version.
SET @page_id = (SELECT id FROM page_definition WHERE code = 'aria:weighment-capture' AND tenant_id = 1);
SET @cur_version_id = (SELECT current_version_id FROM page_definition WHERE id = @page_id);
SET @cur_body = (SELECT body_json FROM page_version WHERE id = @cur_version_id);
SET @needs_fix = (SELECT LOCATE('#form.current_state == ''QC_PRELOAD_APPROVED'' || #form.current_state == ''RELOAD_REQUIRED'' || #form.current_state == ''RELOAD_LOADING''', @cur_body) > 0);
SET @next_version = (SELECT COALESCE(MAX(version), 0) + 1 FROM page_version WHERE page_id = @page_id);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at, created_at)
SELECT @page_id, @next_version, 'PUBLISHED',
