''BILLING_DONE'' ? ''THIRD'' : '''') : #form.flow_variant_code == ''M10.PackLoading'' ? (#form.current_state == ''LOADING_ALLOCATED'' ? ''FIRST'' : (#form.current_state == ''LOADING_COMPLETED'' || #form.current_state == ''WEIGHMENT_2'' || #form.current_state == ''LOADING_COMPLETED_R'' || #form.current_state == ''RELOAD_WEIGHMENT_2'') ? ''SECOND'' : #form.current_state == ''BILLING_DONE'' ? ''THIRD'' : '''') : #form.flow_variant_code == ''M10.TankerOutbound'' ? ((#form.current_state == ''QC_PRELOAD_APPROVED'' || #form.current_state == ''RELOAD_REQUIRED'') ? ''FIRST'' : (#form.current_state == ''QC_SAMPLE_APPROVED'' || #form.current_state == ''UNLOADING_WEIGHMENT'' || #form.current_state == ''RELOAD_LOADING'') ? ''SECOND'' : #form.current_state == ''BILLING_DONE'' ? ''THIRD'' : '''') : #form.flow_variant_code == ''M10.TankerInbound'' ? (#form.current_state == ''QC_APPROVED'' ? ''FIRST'' : #form.current_state == ''WEIGHMENT_1'' ? ''SECOND'' : #form.current_state == ''QTY_RECONCILED'' ? ''THIRD'' : '''') : #form.flow_variant_code == ''M10.PackUnload'' ? (#form.current_state == ''WEIGHMENT_1'' || #form.current_state == ''PLANNING_SHEET_UPDATED'' || #form.current_state == ''UNLOADING_ALLOCATED'' ? ''FIRST'' : #form.current_state == ''UNLOADING_COMPLETED'' ? ''SECOND'' : #form.current_state == ''QUANTITY_RECONCILIATION'' ? ''THIRD'' : '''') : #form.flow_variant_code == ''M10.ReturnStockIn'' ? (#form.current_state == ''DISPATCH_QUEUED'' ? ''FIRST'' : #form.current_state == ''UNLOADING_COMPLETED'' ? ''SECOND'' : '''') : #form.flow_variant_code == ''M10.FGUnloading'' || #form.flow_variant_code == ''M10.StockInward'' ? (#form.current_state == ''WEIGHMENT_1'' || #form.current_state == ''PLANNING_SHEET_UPDATED'' || #form.current_state == ''UNLOADING_ALLOCATED'' ? ''FIRST'' : #form.current_state == ''UNLOADING_COMPLETED'' ? ''SECOND'' : #form.current_state == ''QUANTITY_RECONCILIATION'' ? ''THIRD'' : '''') : ''''"},{"kind":"FormField","name":"w1_prev_display","label":"First Weight (kg) \\u2014 auto (already captured)","type":"number","readOnly":true,"visibleWhen":"#form.weight_seq == ''SECOND'' || #form.weight_seq == ''THIRD''","computedFrom":"#form.w1_weight_kg"},{"kind":"FormField","name":"w2_prev_display","label":"Second Weight (kg) \\u2014 auto (already captured)","type":"number","readOnly":true,"visibleWhen":"#form.weight_seq == ''THIRD''","computedFrom":"#form.w2_weight_kg"},{"kind":"FormField","name":"loaded_weight_kg","label":"Loaded Weight (kg) \\u2014 auto","type":"number","readOnly":true,"visibleWhen":"#form.weight_seq == ''SECOND'' && #form.loading_type != ''UN_LOADING''","computedFrom":"((#form.w1_prev_display - #form.w2_weight_kg) >= 0) * (#form.w1_prev_display - #form.w2_weight_kg) + ((#form.w1_prev_display - #form.w2_weight_kg) < 0) * (0 - (#form.w1_prev_display - #form.w2_weight_kg))"},{"kind":"FormField","name":"loaded_weight_kg","label":"Unloading Weight (kg) \\u2014 auto","type":"number","readOnly":true,"visibleWhen":"#form.weight_seq == ''SECOND'' && (#form.flow_variant_code == ''M10.PackUnload'' || #form.flow_variant_code == ''M10.FGUnloading'' || #form.flow_variant_code == ''M10.StockInward'')","computedFrom":"((#form.w1_prev_display - #form.w2_weight_kg) >= 0) * (#form.w1_prev_display - #form.w2_weight_kg) + ((#form.w1_prev_display - #form.w2_weight_kg) < 0) * (0 - (#form.w1_prev_display - #form.w2_weight_kg))"},{"kind":"FormField","name":"weight_diff_kg","label":"Weight Difference (kg) \\u2014 auto","type":"number","readOnly":true,"visibleWhen":"#form.weight_seq == ''THIRD''","computedFrom":"((#form.w2_prev_display - #form.w3_weight_kg) >= 0) * (#form.w2_prev_display - #form.w3_weight_kg) + ((#form.w2_prev_display - #form.w3_weight_kg) < 0) * (0 - (#form.w2_prev_display - #form.w3_weight_kg))"},{"name":"variance_kg","label":"Variance (kg) \\u2014 auto","type":"number","readOnly":true,"visibleWhen":"#form.weight_seq == ''SECOND'' || #form.weight_seq == ''THIRD''","computedFrom":"#form.weight_seq == ''THIRD'' ? (#form.loading_type == ''LOADING'' ? (#form.w3_weight_kg - #form.w2_weight_kg) : (#form.w2_prev_display - #form.w3_weight_kg)) : (#form.loaded_weight_kg - #form.expected_weight_kg)"},{"kind":"FormField","label":"","name":"current_state","readOnly":true,"type":"text","defaultValueSource":{"field":"current_step","spec":{"type":"entity","entity":"GatePass","filter":{"field":"gp_number","op":"eq","value":"pageData:gp_number"}}}},{"kind":"FormField","name":"flow_variant_code","label":"","type":"text","readOnly":true},{"kind":"FormField","name":"loading_type","label":"","type":"text","readOnly":true}]}}]},{"kind":"Section","title":"Photo Evidence","span":12,"children":[{"kind":"Form","submitLabel":"","bindings":{"fields":[{"name":"wb_display_photo","label":"Weighbridge Display Photo","type":"file","accept":"image/*"},{"name":"vehicle_photo","label":"Vehicle on Bridge Photo","type":"file","accept":"image/*"},{"name":"notes","label":"Notes (any anomaly)","type":"textarea","rows":2}]}}]},{"kind":"Section","span":12,"children":[{"kind":"Stack","direction":"row","gap":12,"justify":"flex-end","wrap":true,"children":[{"kind":"WorkflowActionButton","action":"workflow.transition","label":"Capture & Save Weighment","variant":"primary","confirmRequired":true,"args":{"includeListData":"tankerInboundInvoiceWeights"}}]}]}]},{"kind":"WorkflowFlowBar","sticky":true}]}',
       'Move M10.TankerOutbound RELOAD_LOADING from weight_seq FIRST to SECOND so the per-SKU reload-consume grid (tankerSkuWeights -> m10.tanker-weighment-capture) is reachable.',
       NOW(), NOW()
WHERE @needs_fix = 1;

UPDATE page_version SET status = 'ARCHIVED' WHERE id = @cur_version_id AND @needs_fix = 1;

UPDATE page_definition SET current_version_id = LAST_INSERT_ID() WHERE id = @page_id AND @needs_fix = 1;
